    17→type SocialProvidersType = Parameters<typeof betterAuth>[0]["socialProviders"];
    18→
    19→export const SocialProviders: SocialProvidersType = {};
    20→
    21→if (env.GITHUB_CLIENT_ID && env.GITHUB_CLIENT_SECRET) {
    22→  SocialProviders.github = {
    23→    clientId: env.GITHUB_CLIENT_ID,
    24→    clientSecret: env.GITHUB_CLIENT_SECRET,
    25→  };
    26→}
    27→
