    35→export const auth = betterAuth({
    36→  database: prismaAdapter(prisma, {
    37→    provider: "postgresql",
    38→  }),
    39→  baseURL: getServerUrl(),
    40→  databaseHooks: {
    41→    user: {
    42→      create: {
    43→        after: async (user, _req) => {
    44→          await setupResendCustomer(user);
    45→          // Organization creation is now handled conditionally based on accountType
    46→        },
    47→      },
    48→    },
    49→  },
    50→  advanced: {
    51→    cookiePrefix: SiteConfig.appId,
    52→  },
    53→  emailAndPassword: {
    54→    enabled: true,
    55→    async sendResetPassword({ user, url }) {
    56→      await sendEmail({
    57→        to: user.email,
    58→        subject: "Reset your password",
    59→        html: MarkdownEmail({
    60→          preview: `Reset your password for ${SiteConfig.title}`,
    61→          markdown: `
    62→          Hello,
    63→
    64→          You requested to reset your password.
    65→
    66→          [Click here to reset your password](${url})
    67→          `,
    68→        }),
    69→      });
    70→    },
    71→  },
    72→  user: {
    73→    changeEmail: {
    74→      enabled: true,
    75→      sendChangeEmailVerification: async ({ newEmail, url }) => {
    76→        await sendEmail({
    77→          to: newEmail,
    78→          subject: "Change email address",
    79→          html: MarkdownEmail({
    80→            preview: `Change your email address for ${SiteConfig.title}`,
    81→            markdown: `
    82→            Hello,
    83→
    84→            You requested to change your email address.
    85→
    86→            [Click here to verify your new email address](${url})
    87→            `,
    88→          }),
    89→        });
    90→      },
    91→    },
    92→    deleteUser: {
    93→      enabled: true,
    94→      sendDeleteAccountVerification: async ({ user, token }) => {
    95→        const url = `${getServerUrl()}/auth/confirm-delete?token=${token}&callbackUrl=/auth/goodbye`;
    96→        await sendEmail({
    97→          to: user.email,
    98→          subject: "Delete your account",
    99→          html: MarkdownEmail({
   100→            preview: `Delete your account from ${SiteConfig.title}`,
   101→            markdown: `
   102→            Hello,
   103→
   104→            You requested to delete your account.
   105→
   106→            [Click here to confirm account deletion](${url})
   107→            `,
   108→          }),
   109→        });
   110→      },
   111→    },
   112→  },
   113→  emailVerification: {
   114→    sendVerificationEmail: async ({ user, url }) => {
   115→      await sendEmail({
   116→        to: user.email,
   117→        subject: "Verify your email address",
   118→        html: MarkdownEmail({
   119→          preview: `Verify your email for ${SiteConfig.title}`,
   120→          markdown: `
   121→          Hello,
   122→
   123→          Welcome to ${SiteConfig.title}! Please verify your email address.
   124→
   125→          [Click here to verify your email](${url})
   126→          `,
   127→        }),
   128→      });
   129→    },
   130→  },
   131→  socialProviders: SocialProviders,
   132→  plugins: [
   133→    organization({
   134→      ac: ac,
   135→      roles: roles,
   136→      organizationLimit: 5,
   137→      membershipLimit: 10,
   138→      autoCreateOrganizationOnSignUp: false,
   139→
   140→      organizationCreation: {
   141→        async afterCreate(data) {
   142→          const stripeCustomer = await stripe.customers.create({
   143→            email: data.user.email,
   144→            name: data.organization.name,
   145→            metadata: {
   146→              organizationId: data.organization.id,
   147→            },
   148→          });
   149→          await prisma.organization.update({
   150→            where: { id: data.organization.id },
   151→            data: { stripeCustomerId: stripeCustomer.id },
   152→          });
   153→        },
   154→      },
   155→      async sendInvitationEmail({ id, email }) {
   156→        const inviteLink = `${getServerUrl()}/orgs/accept-invitation/${id}`;
   157→        await sendEmail({
   158→          to: email,
   159→          subject: "You are invited to join an organization",
   160→          html: MarkdownEmail({
   161→            preview: `Join an organization on ${SiteConfig.title}`,
   162→            markdown: `
   163→            Hello,
   164→
   165→            You have been invited to join an organization on ${SiteConfig.title}.
   166→
   167→            [Click here to accept the invitation](${inviteLink})
   168→            `,
   169→          }),
   170→        });
   171→      },
   172→    }),
   173→    magicLink({
   174→      sendMagicLink: async ({ email, url }) => {
   175→        await sendEmail({
   176→          to: email,
   177→          subject: "Sign in to your account",
   178→          html: MarkdownEmail({
   179→            preview: `Magic link to login ${SiteConfig.title}`,
   180→            markdown: `
   181→            Hello,
   182→
   183→            You requested a magic link to sign in to your account.
   184→
   185→            [Click here to sign in](${url})
   186→            `,
   187→          }),
   188→        });
   189→      },
   190→    }),
   191→    admin({}),
   192→    // Warning: always last plugin
   193→    nextCookies(),
   194→  ],
   195→});
