     3→import { Logo } from "@/components/nowts/logo";
     4→import { LoadingButton } from "@/features/form/submit-button";
     5→import { authClient } from "@/lib/auth-client";
     6→import { clsx } from "clsx";
     7→import { useSearchParams } from "next/navigation";
     8→import { useState, type ReactNode } from "react";
     9→
    10→const ProviderData: Record<string, { icon: ReactNode; name: string }> = {
    11→  github: {
    12→    icon: <Logo name="github" size={16} />,
    13→    name: "Github",
    14→  },
    15→  google: {
    16→    icon: <Logo name="google" size={16} />,
    17→    name: "Google",
    18→  },
    19→};
    20→
    21→type ProviderButtonProps = {
    22→  providerId: "github" | "google";
    23→  callbackUrl?: string;
    24→};
    25→
    26→export const ProviderButton = (props: ProviderButtonProps) => {
    27→  const [isLoading, setIsLoading] = useState(false);
    28→  const searchParams = useSearchParams();
    29→
    30→  const getCallbackURL = () => {
    31→    // Priority: prop > search params > default
    32→    if (props.callbackUrl && props.callbackUrl !== "null") {
    33→      return props.callbackUrl.startsWith("/")
    34→        ? props.callbackUrl
    35→        : `/${props.callbackUrl}`;
    36→    }
    37→    const paramUrl = searchParams.get("callbackUrl");
    38→    if (paramUrl && paramUrl !== "null") {
    39→      return paramUrl.startsWith("/") ? paramUrl : `/${paramUrl}`;
    40→    }
    41→    return "/dashboard";
    42→  };
    43→
    44→  const handleSignIn = async () => {
    45→    setIsLoading(true);
    46→    try {
    47→      await authClient.signIn.social({
    48→        provider: props.providerId,
    49→        callbackURL: getCallbackURL(),
    50→      });
    51→    } catch (error) {
    52→      console.error("OAuth sign-in error:", error);
    53→      setIsLoading(false);
    54→    }
    55→  };
    56→
    57→  const data = ProviderData[props.providerId];
    58→
    59→  return (
    60→    <LoadingButton
    61→      loading={isLoading}
    62→      className={clsx({
    63→        "border bg-white text-black hover:bg-white dark:border-neutral-700":
    64→          data.name === "Google",
    65→        "border bg-black text-white hover:bg-gray-950 dark:border-neutral-700":
    66→          data.name === "Github",
    67→      })}
    68→      size="lg"
    69→      onClick={handleSignIn}
    70→    >
    71→      {data.icon}
    72→      <span className="ml-2">Se connecter avec {data.name}</span>
    73→    </LoadingButton>
    74→  );
    75→};
